import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    if n < k or (n == k and k > 1):
        print("NO")
        return

    # Initialize the array with the minimum possible values
    a = [1] * k
    remaining_problems = n - k

    i = 0
    while remaining_problems > 0:
        if i == k - 1 or a[i] * 2 <= a[i + 1]:
            a[i] += 1
            remaining_problems -= 1
        else:
            i += 1

    # Check if the sequence is valid
    valid = True
    for i in range(1, k):
        if not (a[i] > a[i - 1] and a[i] <= 2 * a[i - 1]):
            valid = False
            break

    if valid:
        print("YES")
        print(" ".join(map(str, a)))
    else:
        print("NO")

